      "rawText": "最新最全黄金白银价格炒金神器。7月13日港股三大指数涨跌不一，恒生指数涨0.16%报24213.72，恒生科技指数跌0.96%，国企指数涨0.33%。科网股涨跌不一，石油股活跃，中石油涨超2%；PCB概念股、半导体板块走弱，建滔积层板跌超18%，兆易创新跌超15%。美伊局势紧张，美军宣称打击伊朗，伊朗宣布关闭霍尔木兹海峡遭美否认，该海峡影响全球约20%原油运输，国际油价或获支撑。英伟达CEO否认Rubin Ultra延期传闻，确认明年出货。韩国券商预测SK海力士Q2营业利润60.4万亿韩元，同比暴增556%但低于市场共识，存储芯片板块跳水。 (AI生成)--新浪财经领先金融信息服务平台",
